import{_ as a,o,c as d,a2 as t}from"./chunks/framework.2Gs1zKBA.js";const p=JSON.parse('{"title":"常见问题","description":"","frontmatter":{},"headers":[],"relativePath":"faq/index.md","filePath":"faq/index.md","lastUpdated":1792466090000}'),c={name:"faq/index.md"};function r(l,e,i,n,s,h){return o(),d("div",null,[...e[0]||(e[0]=[t('<h1 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h1><h2 id="close-会让机械臂失能吗" tabindex="-1"><code>close()</code> 会让机械臂失能吗？ <a class="header-anchor" href="#close-会让机械臂失能吗" aria-label="Permalink to &quot;`close()` 会让机械臂失能吗？&quot;">​</a></h2><p>默认不会。它关闭通信资源，但保留电机当前状态。只有在机械臂得到可靠支撑后，才使用 <code>disable()</code> 或 <code>close(disable=True)</code>。</p><h2 id="movej-和-movel-如何选择" tabindex="-1"><code>movej</code> 和 <code>movel</code> 如何选择？ <a class="header-anchor" href="#movej-和-movel-如何选择" aria-label="Permalink to &quot;`movej` 和 `movel` 如何选择？&quot;">​</a></h2><p><code>movej</code> 在关节空间规划，通常更适合快速换位；<code>movel</code> 约束 TCP 走直线，适合插装、涂胶等路径敏感任务。</p><h2 id="为什么-movel-方向与预期不一致" tabindex="-1">为什么 <code>movel</code> 方向与预期不一致？ <a class="header-anchor" href="#为什么-movel-方向与预期不一致" aria-label="Permalink to &quot;为什么 `movel` 方向与预期不一致？&quot;">​</a></h2><p>先确认 <code>frame</code>、<code>mounting</code>、<code>world_frame</code> 与 <code>base_position</code>。基座坐标系不一定等同于现场理解的前、左、上。</p><h2 id="为什么使能后机械臂有下沉或抖动" tabindex="-1">为什么使能后机械臂有下沉或抖动？ <a class="header-anchor" href="#为什么使能后机械臂有下沉或抖动" aria-label="Permalink to &quot;为什么使能后机械臂有下沉或抖动？&quot;">​</a></h2><p>检查型号、安装方向、负载质量、重心、机械安装和 CAN 通信。不要通过盲目提高增益来掩盖配置错误。</p><h2 id="为什么仿真可运行-真机不可运行" tabindex="-1">为什么仿真可运行，真机不可运行？ <a class="header-anchor" href="#为什么仿真可运行-真机不可运行" aria-label="Permalink to &quot;为什么仿真可运行，真机不可运行？&quot;">​</a></h2><p>仿真不验证供电、CAN 接线、终端电阻、设备固件及现场安全条件。按 <a href="/onerobot-A1/safety/can">CAN 排查</a>逐项检查。</p>',11)])])}const _=a(c,[["render",r]]);export{p as __pageData,_ as default};
